block gen_try(block exp, block handler) {
  /*
   * Produce something like:
   *  FORK_OPT <address of handler>
   *  <exp>
   *  TRY_END
   *  JUMP <end of handler>
   *  <handler>
   *
   * If this is not an internal try/catch, then catch and re-raise
   * internal errors to prevent them from leaking.
   *
   * The handler will only execute if we backtrack to the FORK_OPT with
   * an error (exception) that was raised in <exp>.  If <exp> produces no
   * value then FORK_OPT will backtrack (propagate the `empty`, as it
   * were.  If <exp> produces a value then the TRY_END will save the
   * interpreter state, so that any error raised afterwards is wrapped
   * by the TRY_END on backtracking (see execute.c) and thus not caught
   * by this try/catch, as it was not raised in <exp>.
   */
  if (!handler.first && !handler.last)
    // A hack to deal with `.` as the handler; we could use a real NOOP here
    handler = BLOCK(gen_op_simple(DUP), gen_op_simple(POP), handler);
  exp = BLOCK(exp, gen_op_simple(TRY_END), gen_op_target(JUMP, handler));
  return BLOCK(gen_op_target(FORK_OPT, exp), exp, handler);
}

